#!/bin/bash
set -eo pipefail
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B - <<'PY'
import base64,gzip,hashlib,io,json,tarfile
from pathlib import Path
root=Path('/data1/home/sunyiq/china_radiation_16_hpc_20261012_001/execution_v1/raw_recovery_attempt1/coordinate_repair_attempt2')
assert root.parent.is_dir() and not root.parent.is_symlink()
assert not root.exists() and not root.is_symlink()
prepared=[]
for row in [{'name': 'FAILED_BATCH_INPUTS.json', 'bytes': 375103, 'sha256': '08dd954e645ec34442c874483e5e1fdbc3f862e72c2cb9e106e75a88ca301ae9'}, {'name': 'hpc_request_builder.py', 'bytes': 8819, 'sha256': '13aee1977d3ada5eda7e771338cbb5e4dfd4ecd31cd26d1400ae094b0e06712f'}, {'name': 'ALGORITHMS_RESPONSE_BODY.bin', 'bytes': 823173, 'sha256': '74d59ec8ff9194bcfa8f2e4bcdd8fed9422bb36ef10cf9d665a7482b3b80763d'}, {'name': 'ALGORITHMS_TRANSFER_RESULT.json', 'bytes': 429, 'sha256': 'a65e481c5bb8cc8eacc31bd240697775c6ad9579041c9f30dee064e1bb043695'}]:
    path=root.parent/row['name'];assert path.is_file() and not path.is_symlink()
    data=path.read_bytes()
    assert len(data)==row['bytes'] and hashlib.sha256(data).hexdigest()==row['sha256']
    prepared.append((row['name'],data))
packet=base64.b64decode('',validate=True);manifest=json.loads('{"bytes": 12409, "sha256": "b4fa3531a84b7a9dea0a62aba0a4dd246608eb4a3ee3165bf9814fd54c28eb80", "files": [{"name": "hpc_summary_builder.py", "bytes": 7726, "sha256": "a8f611321148881662a89fa30377403d8556c0189713c228e53baaf9f99ca931"}, {"name": "hpc_radiation_reconstruct.py", "bytes": 11565, "sha256": "d13ce1f0586c7f3a908b5dea9fd6e7a62fc1e614f3be4b8e2c841d4584b2e666"}, {"name": "hpc_independent_radiation_review.py", "bytes": 23689, "sha256": "1d3d973207ba39886a17f89576bc01876db3b86cffcab00c6f1b7a57ee050676"}, {"name": "summary_requests.sbatch", "bytes": 1002, "sha256": "69f1f8bd869fe7c61e7c69da88949b895caf8c04162c91a202aa22e82e3ead55"}, {"name": "radiation_numerical.sbatch", "bytes": 1016, "sha256": "a833a030e8fe300490a028a0718774113c716ee3e11772d25c5869c4e2c1784b"}, {"name": "radiation_independent.sbatch", "bytes": 1029, "sha256": "15ead101196ed063d6280cb8b5212c5724663d7d17f7380dfbff732b1ab39146"}]}')
assert len(packet)==manifest['bytes']<=4194304 and hashlib.sha256(packet).hexdigest()==manifest['sha256']
plain=gzip.decompress(packet);assert len(plain)<=134217728
expected={row['name']:row for row in manifest['files']}
with tarfile.open(fileobj=io.BytesIO(plain),mode='r:') as archive:
    members=archive.getmembers()
    assert len(members)==len(expected)==6 and {item.name for item in members}==set(expected)
    for item in members:
        assert item.isfile() and item.name==Path(item.name).name and item.size<=67108864
        data=archive.extractfile(item).read();row=expected[item.name]
        assert len(data)==item.size==row['bytes'] and hashlib.sha256(data).hexdigest()==row['sha256']
        prepared.append((item.name,data))
assert len({name for name,data in prepared})==10
assert sum(p.stat().st_size for p in root.parent.rglob('*') if p.is_file())+len(packet)+sum(len(data) for _,data in prepared)<=4294967296
root.mkdir();(root/'logs').mkdir()
for name,data in prepared:
    with (root/name).open('xb') as stream:stream.write(data)
    print('OWN_COORDINATE_REPAIR_FILE_SHA256='+hashlib.sha256(data).hexdigest()+' '+name)
with (root/'DEPLOYMENT_PACKET.tar.gz').open('xb') as stream:stream.write(packet)
print('OWN_COORDINATE_REPAIR_DEPLOYMENT_DONE')
PY
task_root='/data1/home/sunyiq/china_radiation_16_hpc_20261012_001/execution_v1/raw_recovery_attempt1/coordinate_repair_attempt2'
set +e
task_submit=$(sbatch "$task_root/summary_requests.sbatch" 2>&1)
task_exit=$?
set -e
printf '%s\n' "$task_submit"
printf 'OWN_SUMMARY_SUBMIT_EXIT=%s\n' "$task_exit"
test "$task_exit" = 0
if [[ "$task_submit" =~ ^Submitted\ batch\ job\ ([0-9]+)$ ]]; then
    task_job=${BASH_REMATCH[1]}
else exit 1; fi
printf '%s\n' "$task_job" > "$task_root/OWN_SUMMARY_JOB_ID.txt"
printf 'OWN_REQUEST_BUILD_JOB_ID=%s\nOWN_SUMMARY_JOB_ID=%s\n' "$task_job" "$task_job"
printf 'OWN_SUMMARY_SUBMIT_DONE\n'
